namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ShallowWideMlpCustomTilingData tiling;

    // x: [B, inputSize]
    uint32_t batchSize = context->GetInputShape(0)->GetOriginShape().GetDim(0);
    uint32_t inputSize = context->GetInputShape(0)->GetOriginShape().GetDim(1);

    // w0: [inputSize, hidden1Size], b0: [hidden1Size]
    uint32_t hidden1Size = context->GetInputShape(1)->GetOriginShape().GetDim(1);
    // w1: [hidden1Size, hidden2Size], b1: [hidden2Size]
    uint32_t hidden2Size = context->GetInputShape(3)->GetOriginShape().GetDim(1);
    // w2: [hidden2Size, outputSize], b2: [outputSize]
    uint32_t outputSize = context->GetInputShape(5)->GetOriginShape().GetDim(1);

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_batchSize(batchSize);
    tiling.set_inputSize(inputSize);
    tiling.set_hidden1Size(hidden1Size);
    tiling.set_hidden2Size(hidden2Size);
    tiling.set_outputSize(outputSize);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // Workspace: intermediate y0 (B*hidden1) + y1 (B*hidden2)
    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    size_t y0SizeBytes = static_cast<size_t>(batchSize) * hidden1Size * sizeof(float);
    size_t y1SizeBytes = static_cast<size_t>(batchSize) * hidden2Size * sizeof(float);
    workspaceSizes[0] = y0SizeBytes + y1SizeBytes;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    gert::Shape* y_shape = context->GetOutputShape(0);
    // Output: [B, outputSize]
    int64_t batch = x_shape->GetOriginShape().GetDim(0);
    int64_t outputSize = context->GetInputShape(5)->GetOriginShape().GetDim(1);
    std::vector<int64_t> out_dims = {batch, outputSize};
    y_shape->SetDimNum(out_dims.size());
    for (size_t i = 0; i < out_dims.size(); ++i) {
        y_shape->SetDim(i, out_dims[i]);
    }
    return GRAPH_SUCCESS;
}
